SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_treat_alcolhol(
id varchar(32) NOT NULL,
hospcode varchar(5) NOT NULL,
areacode varchar(8)  NOT NULL,
flag_sent varchar(1)  NOT  NULL,
date_com varchar(14)  NOT  NULL,
b_year varchar(4)  NOT  NULL,
result1 int(10) DEFAULT 0,
result2 int(10) DEFAULT 0,
result3 int(10) DEFAULT 0,
result4 int(10) DEFAULT 0,
PRIMARY KEY (id,hospcode,areacode,b_year),
KEY (hospcode),
KEY (areacode),
KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_treat_alcolhol WHERE id=@id AND b_year=(@b_year+543);


DROP TEMPORARY TABLE IF EXISTS t1;
CREATE TEMPORARY TABLE IF NOT EXISTS t1 (PRIMARY KEY (hospcode,pid)
) ENGINE=MyISAM  IGNORE  AS (
SELECT hospcode,pid,COUNT(1) as total  FROM t_alcoholic WHERE substr(diagcode,1,4) in('Z508')
GROUP BY hospcode,pid
);

INSERT IGNORE INTO s_treat_alcolhol 
(
SELECT
@id,h.hoscode hospcode,concat(h.provcode,h.distcode,SUBSTR(CONCAT('00',h.subdistcode),-2) ,SUBSTR(CONCAT('00',h.mu),-2)) as areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com
,@b_year+543 as b_year
,COUNT(DISTINCT if(substr(diagcode,1,3) in('F10'),CONCAT(t.HOSPCODE,'-',t.pid),NULL)) as B
,COUNT(DISTINCT if(substr(DIAGCODE,1,4) in('F171','F172'),CONCAT(t.HOSPCODE,'-',t.pid),NULL)) as C
,COUNT(DISTINCT if(substr(DIAGCODE,1,4) in('F171','F172') AND t1.total =1 ,CONCAT(t1.HOSPCODE,'-',t1.pid),NULL)) as D
,COUNT(DISTINCT if(substr(DIAGCODE,1,4) in('F171','F172') AND t1.total >1 ,CONCAT(t1.HOSPCODE,'-',t1.pid),NULL)) as E
FROM
chospital h INNER JOIN t_alcoholic t  ON h.hoscode=t.hospcode
LEFT JOIN  t1  ON t.hospcode=t1.hospcode AND t.pid=t1.pid
WHERE h.provcode in(@prov_c)
GROUP BY h.hoscode
);

