SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

DROP TEMPORARY TABLE IF EXISTS t1;
CREATE TEMPORARY TABLE IF NOT EXISTS t1 (PRIMARY KEY (hospcode,pid)
) ENGINE=MyISAM  IGNORE  AS (
SELECT hospcode,pid,COUNT(1) as total  FROM t_alcoholic WHERE substr(diagcode,1,4) in('Z508')
GROUP BY hospcode,pid
);


DROP TEMPORARY TABLE IF EXISTS tx;
CREATE TEMPORARY TABLE IF NOT EXISTS tx  ENGINE=MyISAM DEFAULT CHARSET=utf8 IGNORE  AS
SELECT 
p.hospcode,p.pid,p.CID,p.NAME,p.LNAME,p.BIRTH,p.SEX,p.NATION,p.check_typearea,p.addr,p.check_vhid,p.DISCHARGE
,t.diagcode,IF(substr(diagcode,1,3) in('F10'),'บำบัดเหล้า','บำบัดบุหรี่') AS RESULT
,t1.total 
FROM 	t_person_db p  INNER JOIN	chospital h ON p.hospcode=h.hoscode
		INNER JOIN t_alcoholic t  ON p.hospcode=t.hospcode AND p.PID=t.PID
		LEFT JOIN  t1  ON t.hospcode=t1.hospcode AND t.pid=t1.pid
WHERE  h.provcode in(@prov_c) AND SUBSTR(t.DIAGCODE,1,3) IN('F10','F17')
GROUP BY t.HOSPCODE,t.pid,SUBSTR(t.DIAGCODE,1,3);

